def coeff_pattern(k,n):
    tau=1/(4*H(n))
    if k==0:
        return np.zeros((0,0))
    if k==n:
        return np.array([[-float(tau)]])
    if k==1:
        c1=C(1,n)
        return np.diag([-float(tau),float((c1-1)/(2*c1**2)),float(tau)])
    cnext=B(k+1,n)/(2*(C(k+1,n)+1))
    dnow=(a(k,n)*C(k+1,n)-(h(k+1,n)-1))/(2*C(k,n))
    return np.array([[-float(tau),0,0],[0,float(dnow),-float(a(k,n))/2],[0,-float(a(k,n))/2,float(cnext)]])

